Class Tarjeta
  Define saldo As Integer;
EndClass

Algorithm Comedor
  Define inicial, monto As Integer;
  Read inicial;
  Read monto;
  Define tarjeta As Tarjeta <- New Tarjeta();
  tarjeta.saldo <- inicial;
  If monto > 0 And monto <= tarjeta.saldo Then
    tarjeta.saldo <- tarjeta.saldo - monto;
  EndIf
  Write tarjeta.saldo;
EndAlgorithm

